mapper.select:
SELECT COUNT(*)
  FROM CONTENT_REPORT
 WHERE REPORTER_USER_ID = #{reporterUserId}
   AND REPORTED_AT >= #{since}



   R.STATUS_CODE = #{statusCode}
   AND R.REASON_CODE = #{reasonCode}
   AND R.REPORTED_AT >= #{fromAt}
   AND R.REPORTED_AT < #{toAt}

ORDER BY R.REPORTED_AT DESC, R.REPORT_ID DESC
